      {when:"中3の8月下旬〜9月中旬", what:"応募を受け付け（Googleフォーム、申し込み課題文あり）、締切後に校内選考会（面接）。順位を決めて合否通知・順位告知を出す。", decide:"参加者の決定。応募条件：評定平均3.2以上かつ英語3.5以上、英検2級以上（CEFR B1）、欠席等15回以内。順位＝評定平均×100＋英検CSE×0.21＋スピーチコンテスト入賞30点。面接の結果で参加を認めないこともある", src:"D:2026.4（企画調整会議）／合否通知書（9/10）／順位 告知（9/19）"},
      {when:"中3の9月下旬〜10月中旬", what:"申込と内金の入金。私学財団の助成の申請（交付申請書・推薦決定通知書・指導計画書・事前研修計画書・参加証）。", approve:"校長（推薦）", src:"D:2026 様式第１号（10/5）・様式第２号・指導計画書（10/8）・様式第９号・参加証（10/19）"},
      {when:"中3の10月〜", what:"現地校への出願書類をそろえる（健診・予防接種記録、成績換算表と推薦書、選択授業の希望、自己紹介文、保護者からホストファミリーへの手紙、ビデオ自己紹介、フォトアルバム）。11月上旬に出願費用、12月中旬に残金を入金。", src:"D:アイルランド留学提出書類（チェックリストあり）／2026.4（企画調整会議）"},
      {when:"中3の10月〜高1の7月", what:"事前学習：留学英語（単語帳・週1の自主学習ノート・月1の確認テスト）、留学先国の研究、探究プロジェクトの準備、異文化コミュニケーション。", src:"D:2026.4（企画調整会議）8．事前・事後学習計画"},
      {when:"高1の4〜7月", what:"事前オリエンテーション（生徒 4月、保護者 5月下旬）、渡航前最終オリエンテーション（7月下旬）。留学願（様式1〜5）と同意書・誓約書を出す。", approve:"校長（留学の許可）", src:"D:2026.4（企画調整会議）／留学規程 様式1～5／同意書及び誓約.docx"},
      {when:"高1の8月〜高2の5月", what:"留学（在学留学は10か月）。生徒は毎月1回、学習と生活の状況を報告する。担任または留学担当教員がメールで指導する。私学財団へ留学状況報告書を出す。", src:"D:2026 指導計画書.docx（留学規定第10条）／様式第８号"},
      {when:"帰国後", what:"復学の手続き。探究プロジェクトの英文レポートを書き、国際講演会で英語で講演する。私学財団へ留学完了報告書・交付請求書を出す。", src:"D:指導計画書／様式第５号・第７号"}
