      ["二次試験で部活の公式戦と重なった場合の対処法（2026年度第2回で実施した段取り。今後もこの段取りを踏襲する）：①事前に重なりが分かったら、学校から英検協会へWeb問合せで、対象生徒の2次試験の時間・会場の変更を依頼する。②協会は電話で確認してくる（メールで、折り返しがつながりやすい時間帯と電話番号を聞かれる）。③電話での協会の回答：2級は全国一斉で午後の設定しかなく、時間変更は不可（その生徒は英検か部活かの選択になる）。3級は朝の時間帯への変更が可能で、実際に1名の集合時間を9:15に変更できた（協会からメールで確認が届く）。④当日欠席した生徒がいた場合は、試験後1週間以内に協会のWebお問い合わせフォーム（質問タイトル「不測の事態による欠席」）で連絡する。入力は団体番号・団体名・二次試験日・理由（詳細）のみで、人数や個人情報は不要。具体的な対応は連絡後の協議で決まり、返金・試験日程の変更は不可。⑤出席の確認は、対象生徒の担任へ試験翌日に聞き取る（第2回は前之園先生へSlackで依頼）。", "H:2026-11-09 ユーザー記録（英検協会とのWeb問合せ・電話2026-11-07・メール2026-11-07/08）"]
